<script setup lang="ts">
import { computed,ref,watch,onMounted,onUnmounted } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router'
import { StarIcon,ArrowUpIcon,ArrowDownIcon } from '@heroicons/vue/24/outline'
import { api,bootstrap,ApiError,notify } from '../composables/api'
import { currentDefinition,definitionKey,useCollaborationAction } from '../composables/collaboration'
import type { SavedView,ViewIndex,ViewPreferences } from '../types'
const route=useRoute(),router=useRouter(),perform=useCollaborationAction()
const index=ref<ViewIndex|null>(null),selected=ref<SavedView|null>(null),prefs=ref<ViewPreferences>({version:0,shortcuts:[],default_view_ref:null,labels:{}}),baseline=ref(''),error=ref(''),saving=ref(false),loading=ref(false),preferencesOpen=ref(false)
const mode=ref<'create'|'copy'|'update'|'rename'|'repair'|null>(null),name=ref(''),visibility=ref<'personal'|'shared'>('personal'),formBaseline=ref(''),deleteConfirm=ref(false)
const known=ref<Record<string,SavedView>>({});let selectionGeneration=0,disposed=false
const definition=computed(()=>currentDefinition(route.query)),modified=computed(()=>!!selected.value&&definitionKey(definition.value)!==definitionKey(selected.value.definition))
const selectedRef=computed(()=>typeof route.query.view==='string'?route.query.view:route.query.assignee==='me'?'builtin:assigned_to_me':['unresolved','resolved','ignored','snoozed'].includes(String(route.query.status??'unresolved'))?'builtin:'+String(route.query.status??'unresolved'):'current')
const canReference=computed(()=>selectedRef.value!=='current'&&(!route.query.view||selected.value?.state==='ready'))
const prefDirty=computed(()=>baseline.value!==''&&baseline.value!==JSON.stringify(prefs.value)),editorDirty=computed(()=>mode.value!==null&&formBaseline.value!==JSON.stringify([name.value,visibility.value]))
function mayLeave(){return (!editorDirty.value&&!prefDirty.value)||window.confirm('Discard unsaved view or shortcut changes?')}
onBeforeRouteLeave(mayLeave)
const unload=(e:BeforeUnloadEvent)=>{if(editorDirty.value||prefDirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{window.addEventListener('beforeunload',unload);initialize()});onUnmounted(()=>{disposed=true;selectionGeneration++;window.removeEventListener('beforeunload',unload)})
function title(id:string){return known.value[id]?.name??prefs.value.labels?.[id]??(id.startsWith('builtin:')?id.slice(8).replaceAll('_',' '):'Saved view')}
async function list(page=1){try{const result=await api<ViewIndex>('/views?page='+page);if(disposed)return;index.value=result;for(const v of result.items)known.value[v.id]=v}catch(e){error.value=e instanceof Error?e.message:'Views could not be loaded.'}}
async function loadPreferences(){const p=await api<ViewPreferences>('/view-preferences');if(disposed)return;prefs.value=p;baseline.value=JSON.stringify(p)}
async function loadSelected(){const id=route.query.view,generation=++selectionGeneration;if(typeof id!=='string'){selected.value=null;return}try{const view=await api<SavedView>('/views/'+id);if(disposed||generation!==selectionGeneration)return;selected.value=view;known.value[view.id]=view}catch(e){if(generation===selectionGeneration){selected.value=null;error.value=e instanceof Error?e.message:'This view is unavailable.'}}}
watch(()=>route.query.view,async()=>{deleteConfirm.value=false;await loadSelected();await hydrateShortLink()})
async function initialize(){loading.value=true;try{await Promise.all([list(),loadPreferences()]);await loadSelected();await hydrateShortLink();if(!Object.keys(route.query).length&&prefs.value.default_view_ref)await apply(prefs.value.default_view_ref)}catch(e){error.value=e instanceof Error?e.message:'View preferences could not be loaded.'}finally{loading.value=false}}
async function hydrateShortLink(){if(selected.value?.state==='ready'&&route.query.view&&!Object.keys(route.query).some(k=>!['view','page','per_page'].includes(k)))await apply(selected.value.id,true)}
async function apply(id:string,preservePage=false){if(id==='current')return;if(!mayLeave())return;mode.value=null;error.value='';if(id.startsWith('builtin:')){const state=id.slice(8);await router.replace({query:state==='assigned_to_me'?{status:'unresolved',assignee:'me',range:'24h',sort:'last_seen'}:{status:state,range:'24h',sort:'last_seen'}});return}
 try{const v=known.value[id]??await api<SavedView>('/views/'+id);if(v.state!=='ready'){selected.value=v;known.value[id]=v;await router.replace({query:{view:id}});error.value=v.reason??'Repair this view before applying it.';return}const q:Record<string,string>={view:id,sort:v.definition.sort,range:v.definition.range,status:String(v.definition.filters.status??'unresolved')};for(const[k,value]of Object.entries(v.definition.filters))q[k]=typeof value==='boolean'?(value?'1':'0'):value;if(preservePage){for(const key of ['page','per_page'])if(typeof route.query[key]==='string')q[key]=route.query[key] as string}await router.replace({query:q})}catch(e){error.value=e instanceof Error?e.message:'View unavailable.'}}
function open(next:typeof mode.value){if(editorDirty.value&&!window.confirm('Discard the current view-name draft?'))return;mode.value=next;deleteConfirm.value=false;name.value=next==='create'?'':next==='copy'?(selected.value?.name.slice(0,74)??'Current filters')+' copy':selected.value?.name??'';visibility.value=next==='create'||next==='copy'?'personal':selected.value?.visibility??'personal';formBaseline.value=JSON.stringify([name.value,visibility.value]);error.value=''}
function close(){if(editorDirty.value&&!window.confirm('Discard the unsaved view-name draft?'))return;mode.value=null}
async function save(){if(!name.value.trim()||Array.from(name.value).length>80){error.value='Enter a name of 1–80 characters.';return}saving.value=true;error.value='';try{const existing=selected.value;const isNew=mode.value==='create'||mode.value==='copy';const renaming=mode.value==='rename';const value=renaming?{name:name.value,version:existing!.version}:{...definition.value,name:name.value,visibility:visibility.value,...(!isNew?{version:existing!.version}:{})};const result=await perform<{id:string}>('/views'+(isNew?'':'/'+existing!.id)+(renaming?'/name':''),isNew?'POST':'PATCH',value);mode.value=null;notify(renaming?'View renamed.':'View saved.');await list(index.value?.page??1);await loadSelected();const view=await api<SavedView>('/views/'+result.id);known.value[view.id]=view;if(!renaming)await apply(view.id)}catch(e){error.value=e instanceof Error?e.message:'View could not be saved.'}finally{saving.value=false}}
async function reloadCurrent(){if(!mayLeave())return;mode.value=null;await loadSelected()}
async function remove(){if(!selected.value)return;saving.value=true;error.value='';try{await perform('/views/'+selected.value.id,'DELETE',{version:selected.value.version});deleteConfirm.value=false;mode.value=null;notify('Saved view removed. Errors were not changed.');await router.replace({query:{status:'unresolved'}});await Promise.all([list(),loadPreferences()])}catch(e){error.value=e instanceof Error?e.message:'The view could not be removed.'}finally{saving.value=false}}
async function savePreferences(){saving.value=true;error.value='';try{await perform('/view-preferences','PUT',{version:prefs.value.version,shortcuts:prefs.value.shortcuts,default_view_ref:prefs.value.default_view_ref});await loadPreferences();notify('Personal view preferences saved.')}catch(e){error.value=e instanceof Error?e.message:'Preferences could not be saved.'}finally{saving.value=false}}
async function favorite(id:string){if(!id)return;const existing=prefs.value.shortcuts.find(s=>s.ref===id);if(existing)existing.favorite=!existing.favorite;else{if(prefs.value.shortcuts.length>=100){error.value='At most 100 shortcuts can be saved.';return}prefs.value.shortcuts.push({ref:id,favorite:true,position:prefs.value.shortcuts.length})}await savePreferences()}
async function makeDefault(id:string|null){prefs.value.default_view_ref=id;await savePreferences()}
async function reorder(position:number,delta:number){const rows=prefs.value.shortcuts;const next=position+delta;if(next<0||next>=rows.length)return;[rows[position],rows[next]]=[rows[next]!,rows[position]!];rows.forEach((s,i)=>s.position=i);await savePreferences()}
async function discardPreferences(){if(prefDirty.value&&!window.confirm('Discard the unsaved shortcut changes and load current preferences?'))return;await loadPreferences()}
</script>
<template><section class="saved-views" aria-label="Saved views"><div class="saved-view-toolbar"><label class="saved-view-select">View<select :value="selectedRef" :disabled="loading||saving" @change="apply(($event.target as HTMLSelectElement).value)"><option v-if="selectedRef==='current'" value="current">Current filters</option><option v-if="route.query.view&&!selected" :value="String(route.query.view)">Unavailable saved view</option><optgroup label="Built-in"><option v-for="id in index?.builtins??['builtin:unresolved','builtin:resolved','builtin:ignored','builtin:snoozed']" :key="id" :value="id">{{title(id)}}</option></optgroup><optgroup label="Saved views"><option v-if="selected&&!index?.items.some(v=>v.id===selected!.id)" :value="selected.id">{{selected.name}} · {{selected.visibility}}</option><option v-for="v in index?.items" :key="v.id" :value="v.id">{{v.name}} · {{v.visibility}}{{v.state==='needs_repair'?' · Needs repair':''}}</option></optgroup></select></label><span v-if="selected" class="badge">{{selected.visibility}}</span><span v-if="selected&&modified&&selected.state==='ready'" class="unsaved">Modified</span><button class="button primary" :disabled="saving" @click="open('create')">Save view</button><button v-if="selected?.can_edit&&modified&&selected.state==='ready'" class="button" :disabled="saving" @click="open('update')">Update view</button><button v-if="selected" class="button" :disabled="saving" @click="open('copy')">Save a copy</button><button class="button icon-button" :aria-pressed="!!prefs.shortcuts.find(s=>s.ref===selectedRef)?.favorite" :aria-label="prefs.shortcuts.find(s=>s.ref===selectedRef)?.favorite?'Unfavorite this view':'Favorite this view'" :disabled="saving||!canReference" @click="favorite(selectedRef)"><StarIcon/></button><button class="text-link" :aria-expanded="preferencesOpen" @click="preferencesOpen=!preferencesOpen">Personal shortcuts</button></div><nav v-if="prefs.shortcuts.some(s=>s.favorite)" class="view-shortcuts" aria-label="Favorite views"><button v-for="s in prefs.shortcuts.filter(s=>s.favorite)" :key="s.ref" class="button" :disabled="saving" @click="apply(s.ref)">{{title(s.ref)}}</button></nav><p v-if="selected" class="help">Owned by {{selected.owner}}. {{selected.visibility==='personal'?'Only you can open this view.':'Visible to authorized dashboard users.'}}<span v-if="selected.can_edit" class="view-management"> <button class="text-link" @click="open('rename')">Rename</button> · <button class="text-link danger-link" @click="deleteConfirm=true">Delete view</button></span></p><div v-if="selected?.state==='needs_repair'" class="notice warning"><div><strong>This view needs repair</strong><p>{{selected.reason}}</p><button v-if="selected.can_edit" class="button" @click="open('repair')">Replace with current supported filters</button><button class="button" @click="router.replace({query:{status:'unresolved'}})">Clear view</button></div></div><div v-if="error" class="notice danger" role="alert"><div><p>{{error}}</p><button v-if="selected" class="button" @click="reloadCurrent">Reload current view</button><button v-else class="button" @click="initialize">Try again</button></div></div><form v-if="mode" class="saved-view-editor" @submit.prevent="save"><h3>{{mode==='rename'?'Rename view':mode==='update'?'Update saved definition':mode==='repair'?'Repair view with current filters':mode==='copy'?'Save a personal copy':'Save current inbox filters'}}</h3><label class="field">View name <small>{{Array.from(name).length}} / 80 characters</small><input v-model="name" required :disabled="saving"></label><label v-if="mode!=='rename'" class="field">Visibility<select v-model="visibility" :disabled="saving||!!selected&&!selected.own&&!['create','copy'].includes(mode)"><option value="personal">Personal · only you</option><option value="shared" :disabled="!bootstrap?.capabilities.operate&&!bootstrap?.capabilities.manage">Shared · dashboard users</option></select></label><p class="help">{{mode==='rename'?'Renaming preserves the saved filters.':'Stores permitted filters, sort and relative range—not a frozen result set. Existing definitions are only replaced when you save.'}}</p><div class="inline-actions"><button class="button primary" :disabled="saving">{{saving?'Saving…':mode==='rename'?'Rename view':'Save definition'}}</button><button type="button" class="button" :disabled="saving" @click="close">Cancel</button></div></form><div v-if="deleteConfirm&&selected" class="notice warning"><div><p>Delete “{{selected.name}}”? Its definition and shortcuts become unavailable. Error data is retained.</p><div class="inline-actions"><button class="button" :disabled="saving" @click="remove">Confirm delete view</button><button class="button" :disabled="saving" @click="deleteConfirm=false">Keep view</button></div></div></div><section v-if="preferencesOpen" class="view-preferences"><h3>Your shortcuts and default</h3><p class="help">These preferences are personal and never grant access to another user's view.</p><p>Default: {{prefs.default_view_ref?title(prefs.default_view_ref):'Unresolved (built-in)'}}</p><div class="inline-actions"><button class="button" :disabled="saving||!canReference" @click="makeDefault(selectedRef)">Use current view by default</button><button v-if="prefs.default_view_ref" class="button" :disabled="saving" @click="makeDefault(null)">Reset default</button></div><ul class="shortcut-order"><li v-for="(s,i) in prefs.shortcuts" :key="s.ref"><span>{{title(s.ref)}}</span><button class="button" :disabled="saving" :aria-pressed="s.favorite" @click="favorite(s.ref)">{{s.favorite?'Unfavorite':'Favorite'}}</button><button class="button icon-button" :disabled="saving||i===0" :aria-label="'Move '+title(s.ref)+' earlier'" @click="reorder(i,-1)"><ArrowUpIcon/></button><button class="button icon-button" :disabled="saving||i===prefs.shortcuts.length-1" :aria-label="'Move '+title(s.ref)+' later'" @click="reorder(i,1)"><ArrowDownIcon/></button></li></ul><div v-if="prefDirty" class="notice warning"><div><p>Unsaved shortcut changes remain in this page.</p><button class="button" :disabled="saving" @click="savePreferences">Retry saving shortcuts</button><button class="button" :disabled="saving" @click="discardPreferences">Load latest preferences</button></div></div></section><div v-if="index&&index.last_page>1" class="pagination"><span>{{index.total}} saved views · page {{index.page}} of {{index.last_page}}</span><button class="button" :disabled="index.page<=1" @click="list(index.page-1)">Previous views</button><button class="button" :disabled="index.page>=index.last_page" @click="list(index.page+1)">More views</button></div></section></template>
